/// The bounds of the quads [`quads_inside`] finds filled exactly in
/// `colour`: [`painted_fill`]'s reading, filtered by colour instead of by
/// area.
fn quads_filled_in(
    cx: &mut VisualTestContext,
    selector: &'static str,
    colour: gpui::Hsla,
) -> Vec<Bounds<gpui::ScaledPixels>> {
    quads_inside(cx, selector)
        .into_iter()
        .filter(|q| q.background.as_solid() == Some(colour))
        .map(|q| q.bounds)
        .collect()
}

/// The colour of the claim `role` of the info the inspector shows once the
/// pointer settled on the element tagged `selector`.
fn settled_claim(
    cx: &mut VisualTestContext,
    showcase: &Entity<Showcase>,
    selector: &'static str,
    role: &str,
) -> Option<gpui::Hsla> {
    let info = settle_on(cx, showcase, selector);
    info.and_then(|info| info.colors.iter().find(|c| c.role == role).map(|c| c.value))
}

